                <p>Ceci est la page de contact. Vous pouvez y intégrer un formulaire ou vos coordonnées pour que les utilisateurs puissent vous joindre.</p>
            </div>
        </div>
    </div>

    <script>
        /* --- JavaScript : Logique de changement d'onglet --- */
        function openPage(evt, pageName) {
            // 1. Masquer tous les contenus de pages
            const tabPanes = document.querySelectorAll('.tab-pane');
            tabPanes.forEach(pane => {
                pane.classList.remove('active');
            });

            // 2. Retirer la classe 'active' de tous les boutons
            const tabButtons = document.querySelectorAll('.tab-btn');
            tabButtons.forEach(btn => {
                btn.classList.remove('active');
            });

            // 3. Afficher la page ciblée et activer le bouton cliqué
            document.getElementById(pageName).classList.add('active');
            evt.currentTarget.classList.add('active');
        }
    </script>

