    <!-- Script JavaScript pour la gestion fluide des vues -->
    <script>
        function switchView(viewId) {
            // Masquer toutes les vues
            const views = document.querySelectorAll('.view');
            views.forEach(view => {
                view.classList.remove('active-view');
            });

            // Afficher la vue demandée
            const targetView = document.getElementById(viewId);
            if (targetView) {
                targetView.classList.add('active-view');
                window.scrollTo({ top: 0, behavior: 'smooth' });
            }
        }

        // Gestion de l'historique de navigation par hash (URL)
        window.addEventListener('hashchange', () => {
            const hash = window.location.hash.substring(1);
            if (['home', 'destinations', 'experience', 'contact'].includes(hash)) {
                switchView(hash);
            }
        });

        // Charger la vue initiale selon l'URL au chargement
        window.addEventListener('DOMContentLoaded', () => {
            const hash = window.location.hash.substring(1);
            if (['home', 'destinations', 'experience', 'contact'].includes(hash)) {
                switchView(hash);
            }
        });
    </script>
</body>
