            resize: vertical;
            min-height: 100px;
        }

        .form-group select option {
            background: var(--bg-secondary);
        }

        /* =========================================================================
           12. PIED DE PAGE
           ========================================================================= */
        .footer {
            background-color: #050608;
            border-top: 1px solid var(--border-gold);
            padding: 5rem 0 2rem 0;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 4rem;
            margin-bottom: 4rem;
        }

        .footer-col h4 {
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.2em;
            color: var(--gold);
            margin-bottom: 1.5rem;
        }

        .footer-col p {
            color: var(--text-muted);
            font-size: 0.9rem;
            margin-bottom: 1.5rem;
        }

        .footer-links {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
        }

        .footer-links a {
            text-decoration: none;
            color: var(--text-muted);
            font-size: 0.9rem;
            transition: var(--transition-fast);
        }

        .footer-links a:hover {
            color: var(--gold);
        }

        .footer-bottom {
            border-top: 1px solid rgba(244, 243, 239, 0.1);
            padding-top: 2rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            font-size: 0.8rem;
            color: var(--text-muted);
        }

        .social-links {
            display: flex;
            gap: 1.5rem;
        }

        .social-links a {
            color: var(--text-ivory);
            text-decoration: none;
            font-size: 0.85rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            transition: var(--transition-fast);
        }

        .social-links a:hover {
            color: var(--gold);
        }

        /* =========================================================================
           13. MEDIA QUERIES (RESPONSIVE DESIGN)
           ========================================================================= */
        @media (max-width: 1200px) {
            .footer-grid {
                grid-template-columns: 1fr 1fr;
                gap: 3rem;
            }
            .about-grid {
                gap: 3rem;
            }
        }

        @media (max-width: 900px) {
            .burger-icon {
                display: flex;
            }

            .nav-menu {
                position: fixed;
                top: 90px;
                left: -100%;
                width: 100%;
                height: calc(100vh - 90px);
                background-color: var(--bg-primary);
                flex-direction: column;
                justify-content: center;
                align-items: center;
                gap: 2rem;
                transition: var(--transition-slow);
                border-top: 1px solid var(--border-gold);
            }

            .burger-checkbox:checked ~ .nav-menu {
                left: 0;
            }

            .burger-checkbox:checked ~ .burger-icon span:nth-child(1) {
                transform: translateY(9px) rotate(45deg);
            }
            .burger-checkbox:checked ~ .burger-icon span:nth-child(2) {
                opacity: 0;
            }
            .burger-checkbox:checked ~ .burger-icon span:nth-child(3) {
                transform: translateY(-9px) rotate(-45deg);
            }

            .about-grid,
            .contact-grid {
                grid-template-columns: 1fr;
                gap: 3rem;
            }

            .search-container {
                grid-template-columns: 1fr;
                padding: 1.5rem;
            }
        }

        @media (max-width: 600px) {
            .hero-btns {
                flex-direction: column;
            }
            .destinations-grid,
            .offers-grid,
            .features-grid,
            .testimonials-grid,
            .team-grid {
                grid-template-columns: 1fr;
            }
            .footer-grid {
                grid-template-columns: 1fr;
            }
            .footer-bottom {
                flex-direction: column;
                gap: 1.5rem;
                text-align: center;
            }
        }

        /* Respect des préférences de mouvement réduit */
        @media (prefers-reduced-motion: reduce) {
            html {
                scroll-behavior: auto;
            }
            *, *::before, *::after {
                animation: none !important;
                transition: none !important;
            }
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(20px); }
            to { opacity: 1; transform: translateY(0); }
        }
