            background: #ff4757;
            color: white;
            grid-column: span 2;
        }
        button.clear:hover {
            background: #ff6b81;
        }
    </style>
</head>
<body>

    <div class="calculator">
        <div id="display" class="display">0</div>
        <div class="buttons">
            <button class="clear" onclick="clearCalculator()">AC</button>
            <button class="operator" onclick="appendOperator('/')">/</button>
            <button class="operator" onclick="appendOperator('*')">*</button>

            <button onclick="appendNumber('7')">7</button>
            <button onclick="appendNumber('8')">8</button>
            <button onclick="appendNumber('9')">9</button>
            <button class="operator" onclick="appendOperator('-')">-</button>

            <button onclick="appendNumber('4')">4</button>
            <button onclick="appendNumber('5')">5</button>
            <button onclick="appendNumber('6')">6</button>
            <button class="operator" onclick="appendOperator('+')">+</button>

            <button onclick="appendNumber('1')">1</button>
            <button onclick="appendNumber('2')">2</button>
            <button onclick="appendNumber('3')">3</button>
            <button class="equal" onclick="compute()">=</button>

            <button onclick="appendNumber('0')" style="grid-column: span 2;">0</button>
            <button onclick="appendNumber('.')">.</button>
        </div>
    </div>

    <script>
        /**
         * Agent IA : Developer Agent
         * Implémentation de la logique métier et du contrôleur UI
         */

        // --- 1. Couche Métier (Fonctions pures issues de Code Analyst) ---

        const add = (a, b) => a + b;
        const subtract = (a, b) => a - b;
        const multiply = (a, b) => a * b;
        const divide = (a, b) => {
            if (b === 0) {
                throw new Error("Division par zéro impossible");
            }
            return a / b;
        };

        function calculate(a, operator, b) {
            if (typeof a !== 'number' || typeof b !== 'number' || isNaN(a) || isNaN(b)) {
                throw new Error("Entrées invalides");
            }

            switch (operator) {
                case '+': return add(a, b);
                case '-': return subtract(a, b);
                case '*': return multiply(a, b);
                case '/': return divide(a, b);
                default: throw new Error("Opérateur non supporté");
            }
        }

        // --- 2. Couche Interface Utilisateur & État (UI Controller) ---

        let currentInput = "0";
        let previousInput = null;
        let operation = null;
        let resetScreen = false;

        const displayElement = document.getElementById("display");

        function updateDisplay() {
            displayElement.innerText = currentInput;
        }

        function appendNumber(number) {
            if (currentInput === "0" || resetScreen) {
                currentInput = number;
                resetScreen = false;
            } else {
                // Empêcher d'ajouter plusieurs points décimaux
                if (number === '.' && currentInput.includes('.')) return;
                currentInput += number;
            }
            updateDisplay();
        }

        function appendOperator(op) {
            if (operation !== null) compute();
            previousInput = currentInput;
            operation = op;
            resetScreen = true;
        }

        function compute() {
            if (operation === null || previousInput === null) return;

            const a = parseFloat(previousInput);
            const b = parseFloat(currentInput);

            try {
                const result = calculate(a, operation, b);
                // Gestion des arrondis JavaScript pour éviter les bugs de type 0.1 + 0.2
                currentInput = Math.round(result * 100000000) / 1000000000.toString();
                operation = null;
                previousInput = null;
                resetScreen = true;
            } catch (error) {
                currentInput = error.message;
                operation = null;
                previousInput = null;
                resetScreen = true;
            }
            updateDisplay();
        }

        function clearCalculator() {
            currentInput = "0";
            previousInput = null;
            operation = null;
            resetScreen = false;
            updateDisplay();
        }
    </script>
</body>
</html>
```

