Voici le script utilisé pour automatiser la validation de la logique métier extraite du code de Developer Agent :

```javascript
/**
 * Agent IA : Test Agent
 * Suite de tests unitaires pour la logique de la calculatrice
 */

// --- Importation de la logique métier (copiée depuis le livrable Developer Agent) ---
const add = (a, b) => a + b;
const subtract = (a, b) => a - b;
const multiply = (a, b) => a * b;
const divide = (a, b) => {
    if (b === 0) {
        throw new Error("Division par zéro impossible");
    }
    return a / b;
};

function calculate(a, operator, b) {
    if (typeof a !== 'number' || typeof b !== 'number' || isNaN(a) || isNaN(b)) {
        throw new Error("Entrées invalides");
    }

    switch (operator) {
        case '+': return add(a, b);
        case '-': return subtract(a, b);
        case '*': return multiply(a, b);
        case '/': return divide(a, b);
        default: throw new Error("Opérateur non supporté");
    }
}

// --- Framework de test minimaliste ---
function assertEqual(actual, expected, testName) {
    if (actual === expected) {
        console.log(`✅ [PASS] ${testName}`);
    } else {
        console.error(`❌ [FAIL] ${testName} - Attendu: ${expected}, Obtenu: ${actual}`);
    }
}

function assertThrows(fn, expectedErrorMessage, testName) {
    try {
        fn();
        console.error(`❌ [FAIL] ${testName} - Aucun message d'erreur levé.`);
    } catch (error) {
        if (error.message === expectedErrorMessage) {
            console.log(`✅ [PASS] ${testName}`);
        } else {
            console.error(`❌ [FAIL] ${testName} - Message inattendu: "${error.message}"`);
        }
    }
}

// --- Exécution des Cas de Test ---
console.log("=== DÉBUT DES TESTS UNITAIRES DE LA CALCULATRICE ===\n");

// Tests Opérations de Base
assertEqual(calculate(5, '+', 3), 8, "TC-ADD-01: Addition simple");
assertEqual(calculate(10, '-', 4), 6, "TC-SUB-01: Soustraction simple");
assertEqual(calculate(6, '*', 7), 42, "TC-MUL-01: Multiplication simple");
assertEqual(calculate(20, '/', 4), 5, "TC-DIV-01: Division simple");

// Test Précision Décimale (Gestion des floats JS)
const floatResult = Math.round(calculate(0.1, '+', 0.2) * 100000000) / 100000000;
assertEqual(floatResult, 0.3, "TC-ADD-02: Addition de décimaux (0.1 + 0.2)");

// Tests de Gestion des Erreurs et Robustesse
assertThrows(
