            cursorCircle.style.transform = `translate(${posX - 18}px, ${posY - 18}px)`;
        });

        // Effet hover sur les éléments interactifs
        const interactables = document.querySelectorAll('button, input, .product-card, .logo');
        interactables.forEach(el => {
            el.addEventListener('mouseenter', () => {
                cursorCircle.style.transform += ' scale(1.5)';
                cursorCircle.style.borderColor = '#f3e5ab';
            });
            el.addEventListener('mouseleave', () => {
                cursorCircle.style.transform = cursorCircle.style.transform.replace(' scale(1.5)', '');
                cursorCircle.style.borderColor = 'var(--gold)';
            });
        });

        // --- 2. BASE DE DONNÉES PRODUITS SIMULÉE ---
        const productsData = {
