/**
 * Application Backend - Agence de Voyage (Catalogue & Réservations)
 * Auteur : Developer Agent
 * Stack : Node.js, Express
 */

const express = require('express');
const app = express();
app.use(express.json());

// ==========================================
// BASE DE DONNÉES EN MÉMOIRE (Simulée)
// ==========================================

let destinations = [
    { id: "dest-1", title: "Séjour tout compris à Bali", type: "hôtel", price: 1200, stock: 5, location: "Indonésie" },
    { id: "dest-2", title: "Vol Paris - New York A/R", type: "vol", price: 650, stock: 12, location: "États-Unis" },
    { id: "dest-3", title: "Safari au Kenya", type: "circuit", price: 2400, stock: 3, location: "Kenya" }
];

let bookings = [];
// Stocke les réservations en attente pour libérer le stock après expiration (ex: 15 min)
let tempLocks = new Map(); 

// ==========================================
// 1. MODULE CATALOGUE DES OFFRES
// ==========================================

// Route : Obtenir toutes les destinations avec filtres optionnels (?type=vol&location=Bali)
app.get('/api/destinations', (req, res) => {
    let results = destinations;
    const { type, location, maxPrice } = req.query;

    if (type) {
        results = results.filter(d => d.type.toLowerCase() === type.toLowerCase());
    }
    if (location) {
        results = results.filter(d => d.location.toLowerCase().includes(location.toLowerCase()));
    }
    if (maxPrice) {
        results = results.filter(d => d.price <= parseFloat(maxPrice));
    }

    res.status(200).json({
        success: true,
        count: results.length,
        data: results
    });
});

// Route : Obtenir une offre spécifique par ID
app.get('/api/destinations/:id', (req, res) => {
    const destination = destinations.find(d => d.id === req.params.id);
    if (!destination) {
        return res.status(404).json({ success: false, message: "Offre de voyage non trouvée." });
    }
    res.status(200).json({ success: true, data: destination });
});

// Route (Admin) : Ajouter une nouvelle offre au catalogue
app.post('/api/destinations', (req, res) => {
    const { title, type, price, stock, location } = req.body;

    if (!title || !type || !price || stock === undefined || !location) {
        return res.status(400).json({ success: false, message: "Tous les champs sont obligatoires." });
    }

    const newDestination = {
        id: `dest-${Date.now()}`,
        title,
        type,
        price,
        stock,
        location
    };

    destinations.push(newDestination);
    res.status(201).json({ success: true, message: "Offre créée avec succès", data: newDestination });
});


// ==========================================
// 2. MODULE DE RÉSERVATIONS (BOOKING SERVICE)
// ==========================================

// Route : Créer une réservation (Vérification et verrouillage temporaire du stock)
app.post('/api/bookings', (req, res) => {
    const { destinationId, customerName, customerEmail, travelersCount } = req.body;

    if (!destinationId || !customerName || !customerEmail || !travelersCount) {
        return res.status(400).json({ success: false, message: "Informations de réservation incomplètes." });
    }

    const destination = destinations.find(d => d.id === destinationId);
    if (!destination) {
        return res.status(404).json({ success: false, message: "Destination introuvable." });
    }

    // Vérification du stock disponible
    if (destination.stock < travelersCount) {
        return res.status(409).json({ 
            success: false, 
            message: `Stock insuffisant. Places restantes : ${destination.stock}` 
        });
    }

    // Décrémentation du stock (Simulation du verrouillage)
    destination.stock -= travelersCount;

    const bookingId = `book-${Date.now()}`;
    const newBooking = {
        id: bookingId,
        destinationId,
        title: destination.title,
        customerName,
        customerEmail,
        travelersCount,
        totalPrice: destination.price * travelersCount,
        status: "EN_ATTENTE_PAIEMENT", // Statuts : EN_ATTENTE_PAIEMENT, CONFIRME, ANNULE
        createdAt: new Date()
    };

    bookings.push(newBooking);

    // Simulation d'expiration du panier après 15 minutes si non payé
    const lockTimer = setTimeout(() => {
        const currentBooking = bookings.find(b => b.id === bookingId);
        if (currentBooking && currentBooking.status === "EN_ATTENTE_PAIEMENT") {
            currentBooking.status = "EXPIRE";
            destination.stock += travelersCount; // Remise en stock
            console.log(`[TIMEOUT] Réservation ${bookingId} expirée. Stock restitué.`);
        }
        tempLocks.delete(bookingId);
    }, 15 * 60 * 1000); // 15 minutes

    tempLocks.set(bookingId, lockTimer);

    res.status(201).json({
        success: true,
        message: "Réservation initiée avec succès. Veuillez procéder au paiement dans les 15 minutes.",
        data: newBooking
    });
});

// Route : Consulter l'état d'une réservation
app.get('/api/bookings/:id', (req, res) => {
    const booking = bookings.find(b => b.id === req.params.id);
    if (!booking) {
        return res.status(404).json({ success: false, message: "Réservation introuvable." });
    }
    res.status(200).json({ success: true, data: booking });
});

// Route : Confirmer le paiement d'une réservation
app.post('/api/bookings/:id/pay', (req, res) => {
    const booking = bookings.find(b => b.id === req.params.id);

    if (!booking) {
        return res.status(404).json({ success: false, message: "Réservation introuvable." });
    }
    if (booking.status !== "EN_ATTENTE_PAIEMENT") {
        return res.status(400).json({ success: false, message: `Impossible de payer cette réservation (Statut: ${booking.status}).` });
    }

    // Effacer le timer d'expiration
    if (tempLocks.has(booking.id)) {
        clearTimeout(tempLocks.get(booking.id));
        tempLocks.delete(booking.id);
    }

    booking.status = "CONFIRME";

    res.status(200).json({
        success: true,
        message: "Paiement accepté. Réservation confirmée !",
        data: booking
    });
});

