#### `script.js`
```javascript
// --- LOGIQUE MÉTIER & ÉTAT DE L'APPLICATION ---
const monthsNames = [
    "Janvier", "Février", "Mars", "Avril", "Mai", "Juin", 
    "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"
];

let today = new Date();
let currentMonth = today.getMonth();
let currentYear = today.getFullYear();
let selectedDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());

// Stockage des événements (Format clé "YYYY-MM-DD" : tableau de strings)
let events = JSON.parse(localStorage.getItem('cal_events')) || {};

// Éléments du DOM
const monthYearDisplay = document.getElementById('month-year-display');
const daysGrid = document.getElementById('days-grid');
const prevBtn = document.getElementById('prev-btn');
const nextBtn = document.getElementById('next-btn');
const todayBtn = document.getElementById('today-btn');
const selectedDateTitle = document.getElementById('selected-date-title');
const eventsList = document.getElementById('events-list');
const eventInput = document.getElementById('event-input');
const addEventBtn = document.getElementById('add-event-btn');

// --- FONCTIONS DU CALENDRIER ---

function initCalendar() {
    renderCalendar();
    renderEvents();
}

function renderCalendar() {
    daysGrid.innerHTML = "";
    monthYearDisplay.textContent = `${monthsNames[currentMonth]} ${currentYear}`;

    // Premier jour du mois courant
    let firstDayIndex = new Date(currentYear, currentMonth, 1).getDay();
    // Ajustement pour commencer la semaine un Lundi (0 = Lundi, ... 6 = Dimanche)
    firstDayIndex = (firstDayIndex === 0) ? 6 : firstDayIndex - 1;

    // Dernier jour du mois courant
    let totalDays = new Date(currentYear, currentMonth + 1, 0).getDate();

    // Dernier jour du mois précédent
    let prevTotalDays = new Date(currentYear, currentMonth, 0).getDate();

    // 1. Remplissage des jours du mois précédent (grisés)
    for (let i = firstDayIndex; i > 0; i--) {
        let dayDiv = document.createElement('div');
        dayDiv.classList.add('day', 'inactive');
        dayDiv.textContent = prevTotalDays - i + 1;
        daysGrid.appendChild(dayDiv);
    }

    // 2. Remplissage des jours du mois courant
    for (let i = 1; i <= totalDays; i++) {
        let dayDiv = document.createElement('div');
        dayDiv.classList.add('day');
        dayDiv.textContent = i;

        let dateString = formatDate(new Date(currentYear, currentMonth, i));

        // Vérifier si c'est aujourd'hui
        if (
            i === today.getDate() && 
            currentMonth === today.getMonth() && 
            currentYear === today.getFullYear()
        ) {
            dayDiv.classList.add('today');
        }

        // Vérifier si c'est la date sélectionnée
        if (
            i === selectedDate.getDate() && 
            currentMonth === selectedDate.getMonth() && 
            currentYear === selectedDate.getFullYear()
        ) {
            dayDiv.classList.add('selected');
        }

        // Vérifier s'il y a des événements pour ce jour
        if (events[dateString] && events[dateString].length > 0) {
            let dot = document.createElement('div');
            dot.classList.add('day-event-dot');
            dayDiv.appendChild(dot);
        }

        // Événement de clic sur un jour
        dayDiv.addEventListener('click', () => {
            selectedDate = new Date(currentYear, currentMonth, i);
            renderCalendar();
            renderEvents();
        });

        daysGrid.appendChild(dayDiv);
    }

    // 3. Compléter la grille avec les premiers jours du mois suivant pour garder 42 cases (6 lignes)
    let totalCellsSoFar = firstDayIndex + totalDays;
    let nextDaysCount = (totalCellsSoFar <= 35) ? (35 - totalCellsSoFar) : (42 - totalCellsSoFar);

    for (let i = 1; i <= nextDaysCount; i++) {
        let dayDiv = document.createElement('div');
        dayDiv.classList.add('day', 'inactive');
        dayDiv.textContent = i;
        daysGrid.appendChild(dayDiv);
    }
}

// --- GESTION DES ÉVÉNEMENTS ---

function formatDate(date) {
    let d = new Date(date);
    let month = '' + (d.getMonth() + 1);
    let day = '' + d.getDate();
    let year = d.getFullYear();

    if (month.length < 2) month = '0' + month;
    if (day.length < 2) day = '0' + day;

    return [year, month, day].join('-');
}

function renderEvents() {
    let dateStr = formatDate(selectedDate);
    selectedDateTitle.textContent = `Événements du ${selectedDate.toLocaleDateString('fr-FR', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}`;

    eventsList.innerHTML = "";
    let dayEvents = events[dateStr] || [];

    if (dayEvents.length === 0) {
        eventsList.innerHTML = "<li style='color: var(--text-light); justify-content: center;'>Aucun événement pour cette date.</li>";
        return;
    }

    dayEvents.forEach((eventText, index) => {
        let li = document.createElement('li');
        li.textContent = eventText;

        let deleteBtn = document.createElement('button');
        deleteBtn.innerHTML = '<i class="fa-solid fa-trash"></i>';
        deleteBtn.style.background = 'none';
        deleteBtn.style.border = 'none';
        deleteBtn.style.color = '#ef4444';
        deleteBtn.style.cursor = 'pointer';

        deleteBtn.addEventListener('click', () => {
            deleteEvent(dateStr, index);
        });

        li.appendChild(deleteBtn);
        eventsList.appendChild(li);
    });
}

function addEvent() {
    let text = eventInput.value.trim();
    if (!text) return;

    let dateStr = formatDate(selectedDate);
    if (!events[dateStr]) {
        events[dateStr] = [];
    }

    events[dateStr].push(text);
    localStorage.setItem('cal_events', JSON.stringify(events));

    eventInput.value = "";
    renderCalendar();
    renderEvents();
}

function deleteEvent(dateStr, index) {
    events[dateStr].splice(index, 1);
    if (events[dateStr].length === 0) {
        delete events[dateStr];
    }
    localStorage.setItem('cal_events', JSON.stringify(events));
    renderCalendar();
    renderEvents();
}

// --- ECOUTEURS D'ÉVÉNEMENTS (NAVIGATION) ---

prevBtn.addEventListener('click', () => {
    currentMonth--;
    if (currentMonth < 0) {
        currentMonth = 11;
        currentYear--;
    }
    renderCalendar();
});

nextBtn.addEventListener('click', () => {
    currentMonth++;
    if (currentMonth > 11) {
        currentMonth = 0;
        currentYear++;
    }
    renderCalendar();
});

todayBtn.addEventListener('click', () => {
    currentMonth = today.getMonth();
    currentYear = today.getFullYear();
    selectedDate = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    renderCalendar();
    renderEvents();
});

addEventBtn.addEventListener('click', addEvent);
eventInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
        addEvent();
    }
});

// Lancement initial
initCalendar();
```

