    <!-- Script JavaScript Logique -->
    <script>
        // État de l'application
        let today = new Date();
        let currentMonth = today.getMonth();
        let currentYear = today.getFullYear();
        let selectedDateStr = formatDateKey(today);

        // Charger les événements depuis le LocalStorage ou initialiser vide
        let events = JSON.parse(localStorage.getItem('cal_events')) || {};

        const monthsNames = ["Janvier", "Février", "Mars", "Avril", "Mai", "Juin", "Juillet", "Août", "Septembre", "Octobre", "Novembre", "Décembre"];

        // Initialisation au chargement de la page
        document.addEventListener('DOMContentLoaded', () => {
            updateHeaderDate();
            renderCalendar();
            selectDate(selectedDateStr);
        });

        function updateHeaderDate() {
            const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
            document.getElementById('current-date-header').innerText = today.toLocaleDateString('fr-FR', options);
        }

        // Formater une date en YYYY-MM-DD pour servir de clé
        function formatDateKey(date) {
            const year = date.getFullYear();
            const month = String(date.getMonth() + 1).padStart(2, '0');
            const day = String(date.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        }

        // Afficher le calendrier mensuel
        function renderCalendar() {
            const grid = document.getElementById('calendar-grid');
            grid.innerHTML = '';

            document.getElementById('month-year-display').innerText = `${monthsNames[currentMonth]} ${currentYear}`;

            // Premier jour du mois
            let firstDayIndex = (new Date(currentYear, currentMonth, 1).getDay() + 6) % 7; // Lundi = 0
            // Nombre de jours dans le mois
            let totalDays = new Date(currentYear, currentMonth + 1, 0).getDate();

            // Remplir les espaces vides avant le premier jour du mois
            for (let i = 0; i < firstDayIndex; i++) {
                grid.innerHTML += `<div class="bg-gray-50 rounded-lg opacity-40"></div>`;
            }

            // Remplir les jours du mois
            for (let day = 1; day <= totalDays; day++) {
                let dateStr = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                let isToday = dateStr === formatDateKey(new Date());
                let isSelected = dateStr === selectedDateStr;
                let hasEvents = events[dateStr] && events[dateStr].length > 0;

                let dayClass = "bg-white border rounded-lg p-2 flex flex-col justify-between cursor-pointer transition hover:border-blue-500 relative";
                if (isToday) dayClass += " border-blue-500 bg-blue-50 font-bold";
                if (isSelected) dayClass += " ring-2 ring-blue-600";

                let html = `
                    <div class="${dayClass}" onclick="selectDate('${dateStr}')">
                        <span class="text-sm text-gray-700 ${isToday ? 'text-blue-600 font-bold' : ''}">${day}</span>
                        <div class="mt-1">
                `;

                if (hasEvents) {
                    html += `<div class="w-2 h-2 bg-blue-600 rounded-full mx-auto"></div>`;
                }

                html += `</div></div>`;
                grid.innerHTML += html;
            }
        }

        // Changer de mois (précédent / suivant)
        function changeMonth(direction) {
            currentMonth += direction;
            if (currentMonth > 11) {
                currentMonth = 0;
                currentYear++;
            } else if (currentMonth < 0) {
                currentMonth = 11;
                currentYear--;
            }
            renderCalendar();
        }

        // Revenir au mois/jour actuel
        function goToToday() {
            currentMonth = today.getMonth();
            currentYear = today.getFullYear();
            renderCalendar();
            selectDate(formatDateKey(today));
        }

        // Sélectionner une date spécifique
        function selectDate(dateStr) {
            selectedDateStr = dateStr;
            renderCalendar(); // Rafraîchir pour voir la sélection

            let parts = dateStr.split('-');
            let displayDate = `${parts[2]} ${monthsNames[parseInt(parts[1])-1]} ${parts[0]}`;
            document.getElementById('selected-date-title').innerText = `Événements du ${displayDate}`;

            resetForm();
            renderEventsList();
        }

        // Afficher la liste des événements de la date sélectionnée
        function renderEventsList() {
            const listContainer = document.getElementById('events-list');
            listContainer.innerHTML = '';

            let dayEvents = events[selectedDateStr] || [];

            if (dayEvents.length === 0) {
                listContainer.innerHTML = `<p class="text-gray-400 text-sm italic">Aucun événement pour cette date.</p>`;
                return;
            }

            dayEvents.forEach((event, index) => {
                listContainer.innerHTML += `
                    <div class="flex justify-between items-center p-3 bg-gray-50 border rounded-lg shadow-sm">
                        <div>
                            <h5 class="font-semibold text-gray-800 text-sm">${event.title}</h5>
                            ${event.time ? `<p class="text-xs text-gray-500"><i class="fa-regular fa-clock"></i> ${event.time}</p>` : ''}
                        </div>
                        <div class="flex space-x-2">
                            <button onclick="editEvent('${selectedDateStr}', ${index})" class="text-blue-500 hover:text-blue-700 text-sm">
                                <i class="fa-solid fa-pen"></i>
                            </button>
                            <button onclick="deleteEvent('${selectedDateStr}', ${index})" class="text-red-500 hover:text-red-700 text-sm">
                                <i class="fa-solid fa-trash"></i>
                            </button>
                        </div>
                    </div>
                `;
            });
        }

        // Gérer la soumission du formulaire (Ajout ou Modification)
        function handleFormSubmit(e) {
            e.preventDefault();
            const title = document.getElementById('event-title').value;
            const time = document.getElementById('event-time').value;
            const eventId = document.getElementById('event-id').value;

            if (!events[selectedDateStr]) {
                events[selectedDateStr] = [];
            }

            if (eventId === "") {
                // Ajout
                events[selectedDateStr].push({ title, time });
            } else {
                // Modification
                events[selectedDateStr][parseInt(eventId)] = { title, time };
            }

            saveAndRefresh();
            resetForm();
        }

        // Éditer un événement
        function editEvent(dateStr, index) {
            let event = events[dateStr][index];
            document.getElementById('event-title').value = event.title;
            document.getElementById('event-time').value = event.time || '';
            document.getElementById('event-id').value = index;

            document.getElementById('submit-btn').innerText = "Modifier";
            document.getElementById('submit-btn').className = "flex-1 bg-green-600 text-white py-2 rounded-lg hover:bg-green-700 transition font-medium";
            document.getElementById('cancel-edit-btn').classList.remove('hidden');
        }

        // Supprimer un événement
        function deleteEvent(dateStr, index) {
            events[dateStr].splice(index, 1);
            if (events[dateStr].length === 0) {
                delete events[dateStr];
            }
            saveAndRefresh();
            resetForm();
        }

        // Réinitialiser le formulaire
        function resetForm() {
            document.getElementById('event-form').reset();
            document.getElementById('event-id').value = "";
            document.getElementById('submit-btn').innerText = "Ajouter";
            document.getElementById('submit-btn').className = "flex-1 bg-blue-600 text-white py-2 rounded-lg hover:bg-blue-700 transition font-medium";
            document.getElementById('cancel-edit-btn').classList.add('hidden');
        }

        // Sauvegarder dans LocalStorage et rafraîchir l'interface
        function saveAndRefresh() {
            localStorage.setItem('cal_events', JSON.stringify(events));
            renderCalendar();
            renderEventsList();
        }
    </script>
</body>
</html>
```

