### 🗄️ 2. Base de données : `src/config/database.js`

Gère la connexion à la base de données SQLite et crée la table `tasks` si elle n'existe pas.

```javascript
const sqlite3 = require('sqlite3').verbose();
const path = require('path');

// Chemin vers le fichier de la base de données SQLite
const dbPath = path.resolve(__dirname, '../../database.sqlite');

// Initialisation de la base de données
const db = new sqlite3.Database(dbPath, (err) => {
    if (err) {
        console.error('Erreur lors de la connexion à la base de données SQLite :', err.message);
    } else {
        console.log('Connecté à la base de données SQLite.');
        initializeTable();
    }
});

// Création de la table 'tasks' si elle n'existe pas
function initializeTable() {
    const query = `
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            completed BOOLEAN NOT NULL DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    `;
    db.run(query, (err) => {
        if (err) {
            console.error('Erreur lors de la création de la table :', err.message);
        } else {
            console.log('Table "tasks" vérifiée/créée avec succès.');
        }
    });
}

module.exports = db;
```

