### 🚀 5. Point d'entrée : `src/server.js`

Configure l'application Express, les middlewares globaux et lance le serveur HTTP.

```javascript
const express = require('express');
const taskRoutes = require('./routes/taskRoutes');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware pour parser le JSON dans le corps des requêtes
app.use(express.json());

// Route racine de test
app.get('/', (req, res) => {
    res.json({
        message: 'Bienvenue sur l\'API Task Manager !',
        endpoints: {
            getAllTasks: 'GET /api/tasks',
            getTaskById: 'GET /api/tasks/:id',
            createTask: 'POST /api/tasks',
            updateTask: 'PUT /api/tasks/:id',
            deleteTask: 'DELETE /api/tasks/:id'
        }
    });
});

// Enregistrement des routes de l'API
app.use('/api/tasks', taskRoutes);

// Gestion globale des routes non trouvées (404)
app.use((req, res, next) => {
    res.status(404).json({ error: 'Route non trouvée' });
});

// Gestion globale des erreurs serveur (500)
app.use((err, req, res, next) => {
    console.error(err.stack);
    res.status(500).json({ error: 'Un problème est survenu sur le serveur !' });
});

// Démarrage du serveur
app.listen(PORT, () => {
    console.log(`Serveur démarré et à l'écoute sur http://localhost:${PORT}`);
});
```

