// Gestion du Header fixe au scroll
window.addEventListener('scroll', () => {
    const header = document.getElementById('header');
    if (header) {
        if (window.scrollY > 50) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    }
});

// Affichage dynamique du catalogue sur catalog.html
document.addEventListener('DOMContentLoaded', () => {
    const catalogGrid = document.getElementById('catalog-grid');

    if (catalogGrid) {
        renderTrips(tripsData);

        // Gestion des filtres
        const filterButtons = document.querySelectorAll('.filter-btn');
        filterButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                filterButtons.forEach(btn => btn.classList.remove('active'));
                e.target.classList.add('active');

                const filterValue = e.target.getAttribute('data-filter');
                if (filterValue === 'all') {
                    renderTrips(tripsData);
                } else {
                    const filtered = tripsData.filter(trip => trip.category === filterValue);
                    renderTrips(filtered);
                }
            });
        });
    }
});

// Fonction de rendu des cartes de voyages
function renderTrips(trips) {
    const catalogGrid = document.getElementById('catalog-grid');
    catalogGrid.innerHTML = '';

    trips.forEach(trip => {
        const card = document.createElement('div');
        card.className = 'trip-card';
        card.innerHTML = `
            <div class="trip-img-container">
                <img src="${trip.image}" alt="${trip.title}">
                <span class="trip-badge">${trip.category}</span>
            </div>
            <div class="trip-content">
                <span class="trip-location"><i class="fa-solid fa-location-dot"></i> ${trip.location}</span>
                <h3 class="trip-title">${trip.title}</h3>
                <p class="trip-desc">${trip.description}</p>
                <div class="trip-footer">
                    <div class="trip-price">Dès ${trip.price} € <span>/ pers.</span></div>
                    <button class="btn-primary" onclick="openTripModal(${trip.id})" style="padding: 0.6rem 1.2rem; font-size: 0.75rem;">Découvrir</button>
                </div>
            </div>
        `;
        catalogGrid.appendChild(card);
    });
}

// Système de Modale & Tunnel de Réservation Interactif
function openTripModal(tripId) {
    const trip = tripsData.find(t => t.id === tripId);
    const modal = document.getElementById('trip-modal');
    const modalBody = document.getElementById('modal-body-content');

    modalBody.innerHTML = `
        <span class="trip-location">${trip.location} • ${trip.category}</span>
        <h2>${trip.title}</h2>
        <div class="modal-details-grid">
            <img src="${trip.image}" alt="${trip.title}">
            <div>
                <p style="margin-bottom: 1.5rem; color: var(--text-muted);">${trip.description}</p>
                <p style="font-family: var(--font-heading); font-size: 1.8rem; margin-bottom: 1.5rem; color: var(--accent);">${trip.price} € <span style="font-size:0.9rem; font-family:var(--font-sans); color:var(--text-muted);">par personne</span></p>
                <p style="font-size: 0.9rem;"><i class="fa-solid fa-check" style="color: var(--accent);"></i> Vols en classe Affaires inclus</p>
                <p style="font-size: 0.9rem;"><i class="fa-solid fa-check" style="color: var(--accent);"></i> Transferts en hélicoptère ou véhicule privé</p>
                <p style="font-size: 0.9rem;"><i class="fa-solid fa-check" style="color: var(--accent);"></i> Conciergerie dédiée 24/7</p>
            </div>
        </div>

        <div class="booking-form">
            <h3 style="margin-bottom: 1rem; font-size: 1.3rem;">Réserver ou Demander un Carnet sur-mesure</h3>
            <form id="reservation-form" onsubmit="handleBooking(event, '${trip.title}')">
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
                    <div class="form-group">
                        <label>Nom complet</label>
                        <input type="text" required placeholder="Ex. Victoria Sterling">
                    </div>
                    <div class="form-group">
                        <label>Adresse Email</label>
                        <input type="email" required placeholder="v.sterling@luxury.com">
                    </div>
                </div>
                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1rem;">
                    <div class="form-group">
                        <label>Date souhaitée</label>
                        <input type="date" required>
                    </div>
                    <div class="form-group">
                        <label>Nombre de voyageurs</label>
                        <input type="number" min="1" value="2" required>
                    </div>
                </div>
                <div class="form-group">
                    <label>Demandes particulières (Optionnel)</label>
                    <textarea rows="3" placeholder="Régime alimentaire, transfert en jet privé..."></textarea>
                </div>
                <button type="submit" class="btn-primary" style="width: 100%; text-align: center;">Valider la demande de réservation</button>
            </form>
        </div>
    `;

    modal.classList.add('active');
}

// Fermeture de la modale
document.addEventListener('click', (e) => {
    const modal = document.getElementById('trip-modal');
    const closeModalBtn = document.getElementById('close-modal');

    if (e.target === modal || (closeModalBtn && closeModalBtn.contains(e.target))) {
        modal.classList.remove('active');
    }
});

// Simulation de validation du tunnel de vente
function handleBooking(event, tripTitle) {
    event.preventDefault();
    const modalBody = document.getElementById('modal-body-content');

    modalBody.innerHTML = `
        <div style="text-align: center; padding: 3rem 0;">
            <i class="fa-solid fa-circle-check" style="font-size: 4rem; color: var(--accent); margin-bottom: 1.5rem;"></i>
            <h2 style="margin-bottom: 1rem;">Demande Enregistrée avec Succès</h2>
            <p style="color: var(--text-muted); max-width: 500px; margin: 0 auto 2rem;">
                Merci. Votre demande de séjour pour <strong>"${tripTitle}"</strong> a été transmise à notre conciergerie privée. Un conseiller personnel vous contactera sous 2 heures.
            </p>
            <button class="btn-primary" onclick="document.getElementById('trip-modal').classList.remove('active')">Fermer</button>
        </div>
    `;
}
