### 4. Code Source : `css/style.css` (Design System Luxueux, Sobre & Lumineux)

```css
/* ==========================================
   DESIGN SYSTEM - ÉLIXIR VOYAGES
   ========================================== */

:root {
    --bg-primary: #FCFBFA;
    --bg-light: #F4F1EA;
    --bg-card: #FFFFFF;

    --text-main: #1A1A1A;
    --text-muted: #6B6863;
    --gold: #C5A059;
    --gold-light: #E2CE9F;
    --gold-dark: #9E7B35;

    --border-color: #E2DDD5;

    --font-heading: 'Cormorant Garamond', serif;
    --font-body: 'Montserrat', sans-serif;

    --transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    --shadow: 0 10px 30px rgba(0, 0, 0, 0.05);
    --shadow-hover: 0 20px 40px rgba(197, 160, 89, 0.15);
}

/* RESET & BASE */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-body);
    background-color: var(--bg-primary);
    color: var(--text-main);
    line-height: 1.7;
    overflow-x: hidden;
}

h1, h2, h3, h4 {
    font-family: var(--font-heading);
    font-weight: 600;
    letter-spacing: 0.02em;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

ul {
    list-style: none;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

.container {
    width: 100%;
    max-width: 1280px;
    margin: 0 auto;
    padding: 0 2rem;
}

.section-padding {
    padding: 7rem 0;
}

.bg-light {
    background-color: var(--bg-light);
}

.text-center {
    text-align: center;
}

/* BUTTONS */
.btn {
    display: inline-block;
    padding: 0.9rem 2.2rem;
    font-family: var(--font-body);
    font-size: 0.85rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    cursor: pointer;
    transition: var(--transition);
    border: 1px solid transparent;
}

.btn-primary {
    background-color: var(--text-main);
    color: var(--bg-primary);
    border-color: var(--text-main);
}

.btn-primary:hover {
    background-color: var(--gold);
    border-color: var(--gold);
    color: #FFFFFF;
}

.btn-secondary {
    background-color: transparent;
    color: var(--text-main);
    border-color: var(--text-main);
}

.btn-secondary:hover {
    background-color: var(--text-main);
    color: var(--bg-primary);
}

.btn-outline {
    background-color: transparent;
    border-color: var(--gold);
    color: var(--gold);
}

.btn-outline:hover {
    background-color: var(--gold);
    color: #FFFFFF;
}

.btn-block {
    width: 100%;
}

.link-arrow {
    font-weight: 500;
    letter-spacing: 0.05em;
    color: var(--gold);
    text-transform: uppercase;
    font-size: 0.8rem;
}

.link-arrow:hover {
    color: var(--text-main);
}

/* SUBTITLE */
.subtitle {
    display: block;
    font-family: var(--font-body);
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.25em;
    color: var(--gold);
    margin-bottom: 0.8rem;
}

/* HEADER */
.header {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    background-color: rgba(252, 251, 250, 0.9);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--border-color);
    transition: var(--transition);
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 90px;
}

.logo {
    font-family: var(--font-heading);
    font-size: 1.8rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    color: var(--text-main);
}

.logo span {
    color: var(--gold);
    font-weight: 400;
}

.nav-list {
    display: flex;
    gap: 2.5rem;
}

.nav-link {
    font-size: 0.85rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--text-main);
    position: relative;
}

.nav-link::after {
    content: '';
    position: absolute;
    bottom: -5px;
    left: 0;
    width: 0;
    height: 1px;
    background-color: var(--gold);
    transition: var(--transition);
}

.nav-link:hover::after, .nav-link.active::after {
    width: 100%;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.burger-menu {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    flex-direction: column;
    gap: 6px;
}

.burger-menu span {
    display: block;
    width: 28px;
    height: 2px;
    background-color: var(--text-main);
    transition: var(--transition);
}

/* HERO */
.hero {
    position: relative;
    height: 100vh;
    background: url('https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=2000&q=85') center/cover no-repeat;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
}

.hero-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: linear-gradient(to bottom, rgba(0,0,0,0.3), rgba(0,0,0,0.6));
}

.hero-content {
    position: relative;
    z-index: 2;
    color: #FFFFFF;
    max-width: 800px;
}

.hero-content h1 {
    font-size: 3.8rem;
    margin-bottom: 1.5rem;
    line-height: 1.2;
}

.hero-content p {
    font-size: 1.1rem;
    font-weight: 300;
    margin-bottom: 2.5rem;
    opacity: 0.9;
}

.hero-buttons {
    display: flex;
    gap: 1.5rem;
    justify-content: center;
}

.hero-content .btn-primary {
    background-color: var(--gold);
    border-color: var(--gold);
    color: #FFFFFF;
}

.hero-content .btn-primary:hover {
    background-color: #FFFFFF;
    color: var(--text-main);
    border-color: #FFFFFF;
}

.hero-content .btn-secondary {
    color: #FFFFFF;
    border-color: #FFFFFF;
}

.hero-content .btn-secondary:hover {
    background-color: #FFFFFF;
    color: var(--text-main);
}

/* FEATURES SECTION */
.features-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 3rem;
    margin-top: 4rem;
}

.feature-card {
    background: var(--bg-card);
    padding: 3rem 2rem;
    border: 1px solid var(--border-color);
    transition: var(--transition);
}

.feature-card:hover {
    transform: translateY(-5px);
    box-shadow: var(--shadow-hover);
    border-color: var(--gold-light);
}

.feature-icon {
    font-size: 2.5rem;
    margin-bottom: 1.5rem;
}

.feature-card h3 {
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

.feature-card p {
    color: var(--text-muted);
    font-size: 0.95rem;
}

/* HIGHLIGHTS SECTION */
.flex-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    margin-bottom: 4rem;
}

.highlights-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 2.5rem;
}

/* VOYAGE CARD DESIGN */
.voyage-card {
    background: var(--bg-card);
    border: 1px solid var(--border-color);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.voyage-card:hover {
    transform: translateY(-8px);
    box-shadow: var(--shadow-hover);
}

.voyage-img-wrapper {
    position: relative;
    height: 280px;
    overflow: hidden;
}

.voyage-img-wrapper img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: var(--transition);
}

.voyage-card:hover .voyage-img-wrapper img {
    transform: scale(1.05);
}

.voyage-badge {
    position: absolute;
    top: 1rem;
    right: 1rem;
    background: rgba(252, 251, 250, 0.9);
    padding: 0.4rem 1rem;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    font-weight: 600;
    color: var(--text-main);
}

.voyage-info {
    padding: 2rem;
    display: flex;
    flex-direction: column;
    flex-grow: 1;
}

.voyage-location {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    color: var(--gold);
    margin-bottom: 0.5rem;
}

.voyage-info h3 {
    font-size: 1.4rem;
    margin-bottom: 1rem;
}

.voyage-desc {
    color: var(--text-muted);
    font-size: 0.9rem;
    margin-bottom: 1.5rem;
    flex-grow: 1;
}

.voyage-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    border-top: 1px solid var(--border-color);
    padding-top: 1.2rem;
    margin-top: auto;
}

.voyage-price {
    font-family: var(--font-heading);
    font-size: 1.3rem;
    font-weight: 700;
    color: var(--text-main);
}

.voyage-price span {
    font-family: var(--font-body);
    font-size: 0.75rem;
    color: var(--text-muted);
    font-weight: 400;
}

/* EXPERIENCE SECTION */
.experience-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 5rem;
    align-items: center;
}

.experience-text h2 {
    font-size: 2.8rem;
    margin-bottom: 1.5rem;
    line-height: 1.2;
}

.experience-text p {
    color: var(--text-muted);
    margin-bottom: 2rem;
}

.experience-list {
    margin-bottom: 2.5rem;
}

.experience-list li {
    position: relative;
    padding-left: 2rem;
    margin-bottom: 0.8rem;
    font-weight: 500;
}

.experience-list li::before {
    content: '—';
    position: absolute;
    left: 0;
    color: var(--gold);
}

.experience-image img {
    box-shadow: var(--shadow);
}

/* CONTACT SECTION */
.contact-wrapper {
    max-width: 700px;
    margin: 0 auto;
    background: var(--bg-card);
    padding: 3.5rem;
    border: 1px solid var(--border-color);
    box-shadow: var(--shadow);
}

.contact-form .form-group {
    margin-bottom: 1.8rem;
}

.contact-form label {
    display: block;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 0.6rem;
    font-weight: 500;
}

.contact-form input,
.contact-form select,
.contact-form textarea {
    width: 100%;
    padding: 1rem;
    background: var(--bg-primary);
    border: 1px solid var(--border-color);
    font-family: var(--font-body);
    font-size: 0.95rem;
    color: var(--text-main);
    transition: var(--transition);
}

.contact-form input:focus,
.contact-form select:focus,
.contact-form textarea:focus {
    outline: none;
    border-color: var(--gold);
}

/* CATALOG PAGE SPECIFIC */
.catalog-hero {
    padding: 12rem 0 5rem 0;
    background-color: var(--bg-light);
    border-bottom: 1px solid var(--border-color);
}

.catalog-hero h1 {
    font-size: 3.2rem;
    margin-top: 0.5rem;
    margin-bottom: 1rem;
}

.filters-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: var(--bg-card);
    padding: 1.5rem 2rem;
    border: 1px solid var(--border-color);
