### 5. Conception des Circuits & Décors 3D (`js/track.js`)

Génère un circuit fermé en 3D avec des barrières de sécurité, des portions de route texturées et des éléments de décor futuristes (néons, pylônes lumineux).

```javascript
class TrackBuilder {
    static createTrack(scene, world) {
        // Sol général
        const groundGeo = new THREE.PlaneGeometry(500, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x0a0a12, roughness: 0.9 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Circuit ovale/technologique simple (Piste principale)
        const trackGeo = new THREE.PlaneGeometry(30, 250);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x151525, roughness: 0.5, metalness: 0.5 });

        // Piste Droite 1
        const track1 = new THREE.Mesh(trackGeo, trackMat);
        track1.rotation.x = -Math.PI / 2;
        track1.position.set(0, 0.05, 0);
        scene.add(track1);

        // Physique des barrières et murs du circuit
        const wallShape = new CANNON.Box(new CANNON.Vec3(1, 5, 125));

        const wall1Body = new CANNON.Body({ mass: 0, position: new CANNON.Vec3(-16, 5, 0) });
        wall1Body.addShape(wallShape);
        world.addBody(wall1Body);

        const wall2Body = new CANNON.Body({ mass: 0, position: new CANNON.Vec3(16, 5, 0) });
        wall2Body.addShape(wall2Body);
        world.addBody(wall2Body);

        // Ajout de décors lumineux (Néons latéraux)
        for (let i = -100; i <= 100; i += 20) {
            this.createNeonPillar(scene, -18, i);
            this.createNeonPillar(scene, 18, i);
        }
    }

    static createNeonPillar(scene, x, z) {
        const geometry = new THREE.CylinderGeometry(0.2, 0.2, 4, 8);
        const material = new THREE.MeshBasicMaterial({ color: 0x00f3ff });
        const pillar = new THREE.Mesh(geometry, material);
        pillar.position.set(x, 2, z);
        scene.add(pillar);
    }
}
