### 7. Orchestration & Boucle de Jeu Principale (`js/main.js`)

Coordonne les moteurs 3D (Three.js), physique (Cannon.js), les entités et gère les états globaux du jeu.

```javascript
class GameApp {
    static init() {
        // Configuration Scene 3D
        this.scene = new THREE.Scene();
        this.scene.fog = new THREE.FogExp2(0x05050a, 0.015);

        this.camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);

        this.renderer = new THREE.WebGLRenderer({ antialias: true });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.shadowMap.enabled = true;
        document.getElementById('canvas-container').appendChild(this.renderer.domElement);

        // Lumières
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.4);
        this.scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        this.scene.add(dirLight);

        // Configuration Physique Cannon.js
        this.world = new CANNON.World();
        this.world.gravity.set(0, -9.82, 0);

        // Construction du Circuit
        TrackBuilder.createTrack(this.scene, this.world);

        // Chargement des paramètres du garage
        const settings = GameStorage.getSettings();

        // Création de la voiture joueur
        this.playerCar = new CarPhysics(this.scene, this.world, true, settings.color);
        this.playerCar.body.position.set(0, 2, 80);

        // Création de l'IA adverse
        this.aiCarModel = new CarPhysics(this.scene, this.world, false, "#ff0055");
        this.aiCarModel.body.position.set(5, 2, 80);
        this.aiAI = new RacingAI(this.aiCarModel, RacingAI.getWaypoints());

        this.gameState = 'MENU';
        this.startTime = 0;

        // Gestion du redimensionnement de la fenêtre
        window.addEventListener('resize', () => {
            this.camera.aspect = window.innerWidth / window.innerHeight;
            this.camera.updateProjectionMatrix();
            this.renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Lancement de la boucle de rendu
        this.clock = new THREE.Clock();
        this.animate();
    }

    static updateCarCustomization() {
        const color = document.getElementById('car-color').value;
        const rims = document.getElementById('rim-style').value;
        const engine = document.getElementById('upgrade-engine').value;
        const grip = document.getElementById('upgrade-grip').value;

        const settings = { color, rims, engine, grip };
        GameStorage.saveSettings(settings);

        if (this.playerCar) {
            this.playerCar.setColor(color);
        }
    }

    static startRace() {
        GameUI.startHUD();
        this.gameState = 'RACE';
        this.startTime = performance.now();
        this.playerCar.body.position.set(0, 2, 80);
        this.playerCar.body.velocity.set(0, 0, 0);
        this.playerCar.body.quaternion.set(0, 0, 0, 1);
    }

    static animate() {
        requestAnimationFrame(() => this.animate());

        const delta = this.clock.getDelta();

        if (this.gameState === 'RACE') {
            // Pas de simulation physique (60fps fixe recommandé)
            this.world.step(1 / 60, delta, 3);

            // Mise à jour des véhicules
            this.playerCar.update(delta);
            this.aiAI.update();
            this.aiCarModel.update(delta);

            // Caméra Suiveuse dynamique (Chase Cam)
            const targetPos = this.playerCar.mesh.position;
            const offset = new THREE.Vector3(0, 5, 10);
            const rotatedOffset = offset.applyQuaternion(this.playerCar.mesh.quaternion);
            this.camera.position.lerp(targetPos.clone().add(rotatedOffset), 0.1);
            this.camera.lookAt(targetPos);

            // Chronomètre
            const elapsedTime = performance.now() - this.startTime;
            const minutes = Math.floor(elapsedTime / 60000).toString().padStart(2, '0');
            const seconds = Math.floor((elapsedTime % 60000) / 1000).toString().padStart(2, '0');
            const milliseconds = Math.floor((elapsedTime % 1000) / 10).toString().padStart(2, '0');

            GameUI.updateHUD(this.playerCar.speed, `${minutes}:${seconds}.${milliseconds}`);
        } else {
            // Mode Menu : Rotation lente de la caméra autour de la voiture
            const angle = Date.now() * 0.0005;
            this.camera.position.set(Math.cos(angle) * 15, 5, Math.sin(angle) * 15);
            this.camera.lookAt(0, 0, 0);
        }

        this.renderer.render(this.scene, this.camera);
    }
}

// Initialisation globale au chargement de la page
window.onload = () => {
    GameApp.init();
};
