### 3. Fichier `script.js`
```javascript
// --- CONFIGURATION & VARIABLES GLOBALES ---
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeCanvas);
resizeCanvas();

let currentScreen = 'main-menu';
let playerColor = '#00ffcc';
let selectedTrackIndex = 0;
let gameInterval = null;

// Entrées Clavier
const keys = { z: false, q: false, s: false, d: false, space: false };

window.addEventListener('keydown', (e) => handleKey(e, true));
window.addEventListener('keyup', (e) => handleKey(e, false));

function handleKey(e, isDown) {
    const key = e.key.toLowerCase();
    if (key === 'z' || key === 'w') keys.z = isDown;
    if (key === 'q' || key === 'a') keys.q = isDown;
    if (key === 's') keys.s = isDown;
    if (key === 'd') keys.d = isDown;
    if (e.code === 'Space') keys.space = isDown;
}

// --- GESTION DES ÉCRANS ---
function showScreen(screenId) {
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
    document.getElementById(screenId).classList.add('active');
    currentScreen = screenId;
    if (screenId === 'game-screen') {
        initGame();
    } else {
        clearInterval(gameInterval);
    }
}

function updateCarCustomization() {
    playerColor = document.getElementById('car-color').value;
}

function selectTrack(index, element) {
    selectedTrackIndex = index;
    document.querySelectorAll('.track-card').forEach(c => c.classList.remove('selected'));
    element.classList.add('selected');
}

// --- DÉFINITION DES CIRCUITS ---
const tracks = [
    // Circuit 0 : Ovale simple
    {
        startPos: { x: 400, y: 300, angle: 0 },
        checkpoints: [
            { x: 400, y: 150, radius: 120 },
            { x: 1000, y: 150, radius: 120 },
            { x: 1200, y: 500, radius: 120 },
            { x: 600, y: 700, radius: 150 },
            { x: 200, y: 500, radius: 120 }
        ],
        outerWall: { x: 700, y: 400, rx: 550, ry: 320 },
        innerWall: { x: 700, y: 400, rx: 300, ry: 150 }
    },
    // Circuit 1 : Technique (Sinueux)
    {
        startPos: { x: 300, y: 700, angle: -Math.PI/2 },
        checkpoints: [
            { x: 300, y: 300, radius: 100 },
            { x: 700, y: 200, radius: 100 },
            { x: 1100, y: 400, radius: 100 },
            { x: 900, y: 700, radius: 100 },
            { x: 500, y: 600, radius: 100 }
        ],
        outerWall: { x: 700, y: 450, rx: 500, ry: 350 },
        innerWall: { x: 700, y: 450, rx: 250, ry: 180 }
    }
];

// --- CLASSES DU JEU (PHYSIQUE & IA) ---
class Car {
    constructor(x, y, angle, color, isAI = false) {
        this.x = x;
        this.y = y;
        this.angle = angle;
        this.color = color;
        this.isAI = isAI;

        // Paramètres physiques
        this.speed = 0;
        this.maxSpeed = isAI ? 6.5 : 8;
        this.acceleration = 0.12;
        this.braking = 0.2;
        this.friction = 0.04;
        this.turnSpeed = 0.045;
        this.driftFactor = 0.92; // Plus proche de 1 = glisse plus

        this.width = 30;
        this.height = 16;
        this.currentLap = 1;
        this.nextCheckpoint = 0;

        // Vecteur vitesse pour le dérapage
        this.velocity = { x: 0, y: 0 };
    }

    update() {
        if (!this.isAI) {
            // --- CONTRÔLES JOUEUR (Z, Q, S, D, Espace) ---
            if (keys.z) {
                this.speed = Math.min(this.speed + this.acceleration, this.maxSpeed);
            } else if (keys.s) {
                this.speed = Math.max(this.speed - this.braking, -this.maxSpeed / 3);
            } else {
                if (this.speed > 0) this.speed = Math.max(0, this.speed - this.friction);
                if (this.speed < 0) this.speed = Math.min(0, this.speed + this.friction);
            }

            let currentTurn = this.turnSpeed * (this.speed / this.maxSpeed);
            if (keys.q) this.angle -= currentTurn;
            if (keys.d) this.angle += currentTurn;

            // Système de Drift (Espace)
            if (keys.space && Math.abs(this.speed) > 3) {
                this.driftFactor = 0.97; // Glissade accrue
            } else {
                this.driftFactor = 0.88; // Reprise d'adhérence progressive
            }

        } else {
            // --- INTELLIGENCE ARTIFICIELLE (IA) ---
            let track = tracks[selectedTrackIndex];
            let target = track.checkpoints[this.nextCheckpoint];

            let dx = target.x - this.x;
            let dy = target.y - this.y;
            let targetAngle = Math.atan2(dy, dx);

            // Ajustement progressif de l'angle vers la cible
            let angleDiff = targetAngle - this.angle;
            while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
            while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;

            if (angleDiff > 0.05) this.angle += this.turnSpeed;
            if (angleDiff < -0.05) this.angle -= this.turnSpeed;

            this.speed = Math.min(this.speed + this.acceleration, this.maxSpeed * 0.85);
            this.driftFactor = 0.90;
        }

        // Calcul physique du mouvement vectoriel & dérapage
        let forwardX = Math.cos(this.angle) * this.speed;
        let forwardY = Math.sin(this.angle) * this.speed;

        this.velocity.x = this.velocity.x * this.driftFactor + forwardX * (1 - this.driftFactor);
        this.velocity.y = this.velocity.y * this.driftFactor + forwardY * (1 - this.driftFactor);

        this.x += this.velocity.x;
        this.y += this.velocity.y;

        // Gestion des Checkpoints & Tours
        let track = tracks[selectedTrackIndex];
        let cp = track.checkpoints[this.nextCheckpoint];
        let distToCheckpoint = Math.hypot(this.x - cp.x, this.y - cp.y);

        if (distToCheckpoint < cp.radius) {
            this.nextCheckpoint = (this.nextCheckpoint + 1) % track.checkpoints.length;
            if (this.nextCheckpoint === 0) {
                this.currentLap++;
                if (!this.isAI && this.currentLap > 3) {
                    endGame(true);
                }
            }
        }
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);

        // Effet de traces de pneus en dérapage
        if (Math.abs(this.speed) > 4 && keys.space) {
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.fillRect(-15, -10, 6, 4);
            ctx.fillRect(-15, 6, 6, 4);
        }

        // Corps de la voiture
        ctx.fillStyle = this.color;
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);

        // Pare-brise & Détails
        ctx.fillStyle = '#111';
        ctx.fillRect(-5, -this.height / 2 + 2, 10, this.height - 4);

        // Phares avant
        ctx.fillStyle = '#ffff00';
        ctx.fillRect(this.width / 2 - 4, -this.height / 2 + 2, 4, 4);
        ctx.fillRect(this.width / 2 - 4, this.height / 2 - 6, 4, 4);

        ctx.restore();
    }
}

// --- VARIABLES DE JEU ---
let player;
let aiCars = [];
let startTime = 0;

function initGame() {
    let track = tracks[selectedTrackIndex];
    player = new Car(track.startPos.x, track.startPos.y, track.startPos.angle, playerColor, false);

    aiCars = [
        new Car(track.startPos.x - 40, track.startPos.y - 30, track.startPos.angle, '#ff0055', true),
        new Car(track.startPos.x - 40, track.startPos.y + 30, track.startPos.angle, '#00bfff', true)
    ];

    startTime = Date.now();
    if (gameInterval) clearInterval(gameInterval);
    gameInterval = setInterval(updateGame, 1000 / 60);
}

// --- BOUCLE PRINCIPALE DU JEU ---
function updateGame() {
    // 1. Mises à jour
    player.update();
    aiCars.forEach(ai => ai.update());

    // 2. Rendu Graphique
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawTrack();

    // Dessin des entités
    player.draw();
    aiCars.forEach(ai => ai.draw());

    // 3. Mise à jour du HUD
    document.getElementById('speed-val').innerText = Math.round(Math.abs(player.speed) * 20);
    document.getElementById('lap-val').innerText = Math.min(player.currentLap, 3);

    let elapsedTime = Math.floor((Date.now() - startTime) / 10);
    let minutes = String(Math.floor(elapsedTime / 6000)).padStart(2, '0');
    let seconds = String(Math.floor((elapsedTime % 6000) / 100)).padStart(2, '0');
    let milliseconds = String(elapsedTime % 100).padStart(2, '0');
    document.getElementById('time-val').innerText = `${minutes}:${seconds}.${milliseconds}`;
}

// --- RENDU DES CIRCUITS ---
function drawTrack() {
    let track = tracks[selectedTrackIndex];

    // Sol (Asphalte)
    ctx.fillStyle = '#1e2433';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Piste (Forme ovale/circulaire stylisée)
    ctx.strokeStyle = '#2d3748';
    ctx.lineWidth = 140;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.arc(track.outerWall.x, track.outerWall.y, track.outerWall.rx - 100, 0, Math.PI * 2);
    ctx.stroke();

    // Bordures lumineuses Néon de la piste
    ctx.strokeStyle = '#00ffcc';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(track.outerWall.x, track.outerWall.y, track.outerWall.rx - 30, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = '#ff007f';
    ctx.beginPath();
    ctx.arc(track.innerWall.x, track.innerWall.y, track.innerWall.rx + 20, 0, Math.PI * 2);
    ctx.stroke();

    // Ligne de départ / arrivée
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 6;
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(track.startPos.x, track.startPos.y - 70);
    ctx.lineTo(track.startPos.x, track.startPos.y + 70);
    ctx.stroke();
    ctx.setLineDash([]); // Reset du dash
}

function endGame(won) {
    clearInterval(gameInterval);
    document.getElementById('result-title').innerText = won ? "VICTOIRE !" : "COURSE TERMINÉE";
    document.getElementById('result-text').innerText = `Temps total : ${document.getElementById('time-val').innerText}`;
    showScreen('gameover-screen');
}
```

En tant que **Developer Agent**, j'ai développé l'intégralité du jeu de course automobile 2D en Top-Down demandé. Le code respecte strictement les contraintes : HTML5, CSS3 et JavaScript natif (Canvas 2D), sans aucune bibliothèque externe, réparti proprement dans les trois fichiers demandés (`index.html`, `style.css`, `script.js`).

