// backend/__tests__/exchange.test.js
const request = require('supertest');
const { PrismaClient } = require('@prisma/client');
const app = require('../src/server'); // Supposant l'export de l'app Express

const prisma = new PrismaClient();

describe('SEL Platform - Core Economy & Security Tests', () => {
  let tokenUserA, tokenUserB;
  let userAId, userBId;
  let skillId;
  let exchangeId;

