## 4. Code Sécurisé Corrigé pour le Backend (`exchangeController.js` / `server.js`)

Voici l'ajustement apporté à la route de validation pour garantir l'intégrité infaillible de la monnaie temps :

```javascript
// Route mise à jour avec vérification de solvabilité et anti-double validation
app.put('/api/exchanges/:id/complete', authenticateToken, async (req, res) => {
  const { id } = req.params;
  try {
    const exchange = await prisma.exchange.findUnique({ 
      where: { id },
      include: { requester: true }
    });

    if (!exchange) return res.status(404).json({ error: "Échange introuvable" });
    if (exchange.status === 'COMPLETED') return res.status(400).json({ error: "Cet échange a déjà été validé" });

    if (exchange.providerId !== req.user.userId && exchange.requesterId !== req.user.userId) {
      return res.status(403).json({ error: "Accès refusé" });
    }

    // Vérification cruciale : Le demandeur possède-t-il assez de crédits ?
    if (exchange.requester.credits < exchange.hours) {
      return res.status(400).json({ error: "Crédits insuffisants chez le demandeur pour valider cet échange." });
    }

    // Transaction ACID sécurisée
    const [updatedExchange] = await prisma.$transaction([
      prisma.exchange.update({
        where: { id },
        data: { status: 'COMPLETED' }
      }),
      prisma.user.update({
        where: { id: exchange.requesterId },
        data: { credits: { decrement: exchange.hours } }
      }),
      prisma.user.update({
        where: { id: exchange.providerId },
        data: { credits: { increment: exchange.hours } }
      })
    ]);

    res.json({ message: "Échange validé et crédits transférés avec succès !", updatedExchange });
  } catch (error) {
    res.status(500).json({ error: "Erreur lors de la validation de l'échange" });
  }
});
```

