const modal = document.getElementById('auth-modal');
let isRegisterMode = false;

document.getElementById('btn-login').addEventListener('click', () => openAuthModal(false));
document.getElementById('btn-register').addEventListener('click', () => openAuthModal(true));
document.getElementById('close-modal').addEventListener('click', () => modal.classList.add('hidden'));

function openAuthModal(register) {
    isRegisterMode = register;
    document.getElementById('modal-title').textContent = register ? 'Inscription' : 'Connexion';
    document.getElementById('group-name').style.display = register ? 'block' : 'none';
    document.getElementById('auth-submit-btn').textContent = register ? "S'inscrire" : "Se connecter";
    document.getElementById('auth-switch-text').innerHTML = register ? 
        'Déjà un compte ? <a href="#" id="auth-switch">Se connecter</a>' : 
        'Pas encore de compte ? <a href="#" id="auth-switch">S\'inscrire</a>';
    modal.classList.remove('hidden');
    setupAuthSwitch();
}

function setupAuthSwitch() {
    document.getElementById('auth-switch').addEventListener('click', (e) => {
        e.preventDefault();
        openAuthModal(!isRegisterMode);
    });
}

document.getElementById('auth-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const email = document.getElementById('auth-email').value;
    const password = document.getElementById('auth-password').value;

    if (isRegisterMode) {
        const name = document.getElementById('auth-name').value;
        if(users.find(u => u.email === email)) {
            alert('Cet email est déjà utilisé.');
            return;
        }
        const newUser = { id: 'u_' + Date.now(), name, email, password, credits: 3 }; // 3 crédits offerts à l'inscription !
        users.push(newUser);
        localStorage.setItem('timeshare_users', JSON.stringify(users));
        currentUser = newUser;
    } else {
        const user = users.find(u => u.email === email && u.password === password);
        if (!user) {
            alert('Identifiants incorrects.');
            return;
        }
        currentUser = user;
    }

    localStorage.setItem('timeshare_current_user', JSON.stringify(currentUser));
    modal.classList.add('hidden');
    updateAuthUI();
    renderAnnouncements();
    switchView('catalog');
});

document.getElementById('btn-logout').addEventListener('click', () => {
    currentUser = null;
    localStorage.removeItem('timeshare_current_user');
    updateAuthUI();
    switchView('catalog');
    renderAnnouncements();
});

function updateAuthUI() {
    const isAuth = currentUser !== null;
    document.getElementById('auth-buttons').classList.toggle('hidden', isAuth);
    document.getElementById('user-pill').classList.toggle('hidden', !isAuth);

    document.getElementById('nav-add').classList.toggle('hidden', !isAuth);
    document.getElementById('nav-messages').classList.toggle('hidden', !isAuth);
    document.getElementById('nav-profile').classList.toggle('hidden', !isAuth);

    if (isAuth) {
        // Rafraîchir les données utilisateur depuis le store global
        currentUser = users.find(u => u.id === currentUser.id) || currentUser;
        document.getElementById('header-credits').textContent = currentUser.credits;
        document.getElementById('user-name-display').textContent = currentUser.name;
        updateUnreadBadge();
    }
}

// --- CATALOGUE & FILTRES ---
function renderAnnouncements() {
    const grid = document.getElementById('announcements-grid');
    const search = document.getElementById('search-input').value.toLowerCase();
    const cat = document.getElementById('filter-category').value;
    const type = document.getElementById('filter-type').value;
    const loc = document.getElementById('filter-location').value.toLowerCase();

    const filtered = announcements.filter(a => {
        const matchSearch = a.title.toLowerCase().includes(search) || a.desc.toLowerCase().includes(search);
        const matchCat = cat === '' || a.category === cat;
        const matchType = type === '' || a.type === type;
        const matchLoc = loc === '' || a.location.toLowerCase().includes(loc);
        return matchSearch && matchCat && matchType && matchLoc;
    });

    grid.innerHTML = filtered.length === 0 ? '<p>Aucune annonce trouvée.</p>' : filtered.map(a => `
        <div class="card">
            <div>
                <div class="card-header">
                    <span class="tag ${a.type}">${a.type === 'offre' ? 'Offre' : 'Demande'}</span>
                    <span class="credit-pill">🪙 1h = 1 crédit</span>
                </div>
                <h3>${a.title}</h3>
                <div class="card-meta">
                    <span>📍 ${a.location}</span>
                    <span>👤 ${a.userName}</span>
                </div>
                <p class="card-desc">${a.desc}</p>
            </div>
            ${currentUser && currentUser.id !== a.userId ? 
                `<button class="btn primary full" onclick="contactUser('${a.userId}', '${a.id}')">Contacter (${a.userName})</button>` : 
                ''}
        </div>
    `).join('');
}

['search-input', 'filter-category', 'filter-type', 'filter-location'].forEach(id => {
    document.getElementById(id).addEventListener('input', renderAnnouncements);
    document.getElementById(id).addEventListener('change', renderAnnouncements);
});

// --- CRÉATION D'ANNONCE ---
document.getElementById('announcement-form').addEventListener('submit', (e) => {
    e.preventDefault();
    if (!currentUser) return;

    const newAnn = {
        id: 'a_' + Date.now(),
        userId: currentUser.id,
        userName: currentUser.name,
        type: document.getElementById('ann-type').value,
        title: document.getElementById('ann-title').value,
        category: document.getElementById('ann-category').value,
        location: document.getElementById('ann-location').value,
        desc: document.getElementById('ann-desc').value
    };

    announcements.unshift(newAnn);
    localStorage.setItem('timeshare_announcements', JSON.stringify(announcements));
    document.getElementById('announcement-form').reset();
    renderAnnouncements();
    switchView('catalog');
});

// --- MESSAGERIE & LOGIQUE DE TRANSACTION (MONNAIE TEMPS) ---
function contactUser(targetUserId, announcementId) {
    if (!currentUser) return;

    // Vérifier si une conversation existe déjà pour cette annonce
    let conv = messages.find(m => m.announcementId === announcementId && 
        (m.senderId === currentUser.id || m.receiverId === currentUser.id));

    if (!conv) {
        conv = {
            id: 'm_' + Date.now(),
            senderId: currentUser.id,
            receiverId: targetUserId,
            announcementId: announcementId,
            text: 'Bonjour, je suis intéressé(e) par votre annonce.',
            timestamp: Date.now(),
            validated: false
        };
        messages.push(conv);
        localStorage.setItem('timeshare_messages', JSON.stringify(messages));
    }

    switchView('messages');
    selectConversation(conv.id);
}

function renderConversations() {
    if (!currentUser) return;
    const list = document.getElementById('conversations-list');

    // Obtenir les conversations uniques liées à l'utilisateur
    const userConvs = messages.filter(m => m.senderId === currentUser.id || m.receiverId === currentUser.id);

    list.innerHTML = userConvs.length === 0 ? '<div class="conv-item">Aucune conversation</div>' : userConvs.map(c => {
        const otherId = c.senderId === currentUser.id ? c.receiverId : c.senderId;
        const otherUser = users.find(u => u.id === otherId) || { name: 'Utilisateur' };
        const ann = announcements.find(a => a.id === c.announcementId) || { title: 'Service' };

        return `
            <div class="conv-item ${activeChatId === c.id ? 'active' : ''}" onclick="selectConversation('${c.id}')">
                <strong>${otherUser.name}</strong>
                <p style="font-size:0.8rem; color:var(--text-muted);">${ann.title}</p>
            </div>
        `;
    }).join('');
}

function selectConversation(convId) {
    activeChatId = convId;
    renderConversations();

    const conv = messages.find(m => m.id === convId);
    if (!conv) return;

    const otherId = conv.senderId === currentUser.id ? conv.receiverId : conv.senderId;
    const otherUser = users.find(u => u.id === otherId);
    const ann = announcements.find(a => a.id === conv.announcementId);
    const chatArea = document.getElementById('chat-area');

    chatArea.innerHTML = `
        <div style="padding: 1rem; border-bottom: 1px solid var(--border-color); background:var(--card-bg);">
            <strong>Discussion avec ${otherUser.name}</strong> au sujet de : <em>${ann ? ann.title : 'Service'}</em>
        </div>

        ${conv.validated ? 
            `<div class="transaction-box"><span>✅ Service validé (1 crédit transféré)</span></div>` :
            `<div class="transaction-box">
                <span>Le service a-t-il été rendu (1 heure = 1 crédit) ?</span>
                <button class="btn primary" onclick="validateService('${conv.id}')">Valider l'échange (1h)</button>
            </div>`
        }

        <div class="chat-messages" id="chat-msgs">
            <div class="message ${conv.senderId === currentUser.id ? 'sent' : 'received'}">
                ${conv.text}
            </div>
        </div>

        <div class="chat-input-bar">
            <input type="text" id="chat-input" placeholder="Écrivez votre message..." onkeypress="handleChatKeyPress(event, '${conv.id}')">
            <button class="btn primary" onclick="sendChatMessage('${conv.id}')">Envoyer</button>
        </div>
    `;
}

function sendChatMessage(convId) {
    const input = document.getElementById('chat-input');
    const text = input.value.trim();
    if (!text) return;

    // Pour simplifier le prototype, on met à jour le texte du message de la conversation
    const conv = messages.find(m => m.id === convId);
    conv.text = text;
    conv.senderId = currentUser.id; // Alternance simplifiée
    localStorage.setItem('timeshare_messages', JSON.stringify(messages));

    selectConversation(convId);
}

function handleChatKeyPress(e, convId) {
    if (e.key === 'Enter') sendChatMessage(convId);
}

// LOGIQUE MÉTIER CLEF : TRANSFERT DE CRÉDIT DE TEMPS (1h = 1 crédit)
function validateService(convId) {
    const conv = messages.find(m => m.id === convId);
    if (conv.validated) return;

    // Le prestataire est celui qui propose l'offre (ou le créateur de l'annonce)
    const ann = announcements.find(a => a.id === conv.announcementId);
    if (!ann) return;

    const providerId = ann.userId;
    const requesterId = providerId === conv.senderId ? conv.receiverId : conv.senderId;

    const provider = users.find(u => u.id === providerId);
    const requester = users.find(u => u.id === requesterId);

    if (requester.credits < 1) {
        alert("Le demandeur n'a pas assez de crédits de temps (solde insuffisant).");
        return;
    }

    // Transfert effectif
    requester.credits -= 1;
    provider.credits += 1;
    conv.validated = true;

    // Sauvegarde
    localStorage.setItem('timeshare_users', JSON.stringify(users));
    localStorage.setItem('timeshare_messages', JSON.stringify(messages));

    // Mettre à jour l'utilisateur courant en session
    currentUser = users.find(u => u.id === currentUser.id);
    localStorage.setItem('timeshare_current_user', JSON.stringify(currentUser));

    updateAuthUI();
    selectConversation(convId);
    alert('Échange validé avec succès ! 1 crédit a été transféré.');
}

function updateUnreadBadge() {
    // Optionnel / Minimaliste
}

// --- PROFIL & TABLEAU DE BORD ---
function renderProfile() {
    if (!currentUser) return;
    document.getElementById('profile-credits').textContent = currentUser.credits;

    const myAnns = announcements.filter(a => a.userId === currentUser.id);
    const container = document.getElementById('my-announcements');

    container.innerHTML = myAnns.length === 0 ? '<p>Vous n\'avez publié aucune annonce.</p>' : myAnns.map(a => `
        <div class="card" style="margin-bottom: 0.5rem;">
            <div class="card-header">
                <span class="tag ${a.type}">${a.type}</span>
                <button class="btn-text" style="color:#ef4444;" onclick="deleteAnnouncement('${a.id}')">Supprimer</button>
            </div>
            <h4>${a.title}</h4>
            <p style="font-size:0.85rem; color:var(--text-muted);">${a.location}</p>
        </div>
    `).join('');
}

function deleteAnnouncement(id) {
    announcements = announcements.filter(a => a.id !== id);
    localStorage.setItem('timeshare_announcements', JSON.stringify(announcements));
    renderProfile();
    renderAnnouncements();
}

function setupEventListeners() {
    // Utilitaires globaux exposés pour les onclick dynamiques
    window.contactUser = contactUser;
    window.selectConversation = selectConversation;
    window.sendChatMessage = sendChatMessage;
    window.handleChatKeyPress = handleChatKeyPress;
    window.validateService = validateService;
    window.deleteAnnouncement = deleteAnnouncement;
}
