### 3. `script.js`
Logique interactive complète en JavaScript vanilla (ES6+), incluant la gestion du DOM, l'effet de frappe (typing effect), la simulation de réponses dynamiques contextuelles et la persistance via `localStorage`.

```javascript
/**
 * Developer Agent - Logique de l'application Chat
 */

document.addEventListener('DOMContentLoaded', () => {
    // --- Sélecteurs DOM ---
    const userInput = document.getElementById('userInput');
    const sendBtn = document.getElementById('sendBtn');
    const messagesContainer = document.getElementById('messagesContainer');
    const welcomeScreen = document.getElementById('welcomeScreen');
    const newChatBtn = document.getElementById('newChatBtn');
    const historyContainer = document.getElementById('historyContainer');
    const menuToggle = document.getElementById('menuToggle');
    const sidebar = document.getElementById('sidebar');

    // --- État de l'application ---
    let chats = JSON.parse(localStorage.getItem('chat_history')) || [];
    let currentChatId = localStorage.getItem('current_chat_id') || null;

    // --- Banque de réponses simulées de l'IA ---
    const aiResponses = [
        "C'est une excellente question ! En tant que Developer Agent, je peux vous aider à concevoir, structurer et optimiser votre code.",
        "Le développement web moderne repose sur une bonne séparation des préoccupations : HTML pour la structure, CSS pour le design, et JS pour l'interactivité.",
        "J'ai bien analysé votre demande. Voici une suggestion d'implémentation propre, modulaire et sans dépendance externe.",
        "Le stockage local (`localStorage`) est parfait pour persister de petites données directement dans le navigateur sans nécessiter de backend.",
        "Absolument ! Souhaitez-vous que j'approfondisse ce point ou que je vous écrive un exemple pratique ?"
    ];

    // --- Initialisation ---
    initApp();

    // --- Gestion des Événements ---

    // Activation du bouton d'envoi selon la saisie
    userInput.addEventListener('input', () => {
        // Ajustement automatique de la hauteur du textarea
        userInput.style.height = 'auto';
        userInput.style.height = `${Math.min(userInput.scrollHeight, 200)}px`;

        // Gestion de l'état du bouton
        sendBtn.disabled = userInput.value.trim() === '';
    });

    // Envoi par touche Entrée (sauf Maj + Entrée)
    userInput.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            if (!sendBtn.disabled) {
                handleSendMessage();
            }
        }
    });

    sendBtn.addEventListener('click', handleSendMessage);

    // Nouvelle discussion
    newChatBtn.addEventListener('click', () => {
        createNewChat();
        if (window.innerWidth <= 768) sidebar.classList.remove('open');
    });

    // Toggle menu mobile
    menuToggle.addEventListener('click', () => {
        sidebar.classList.toggle('open');
    });

    // --- Fonctions Métier ---

    function initApp() {
        renderHistory();
        if (currentChatId && chats.some(c => c.id === currentChatId)) {
            loadChat(currentChatId);
        } else if (chats.length > 0) {
            loadChat(chats[0].id);
        } else {
            createNewChat();
        }
    }

    function createNewChat() {
        const newChat = {
            id: 'chat_' + Date.now(),
            title: 'Nouvelle discussion',
            messages: []
        };
        chats.unshift(newChat);
        currentChatId = newChat.id;
        saveToLocalStorage();
        renderHistory();
        renderMessages([]);
    }

    function handleSendMessage() {
        const text = userInput.value.trim();
        if (!text) return;

        // Réinitialisation du champ
        userInput.value = '';
        userInput.style.height = 'auto';
        sendBtn.disabled = true;

        // Masquer l'écran d'accueil si présent
        if (welcomeScreen) welcomeScreen.style.display = 'none';

        // Récupérer la conversation actuelle
        let currentChat = chats.find(c => c.id === currentChatId);
        if (!currentChat) {
            createNewChat();
            currentChat = chats[0];
        }

        // Si c'est le premier message, renommer le titre du chat
        if (currentChat.messages.length === 0) {
            currentChat.title = text.length > 25 ? text.substring(0, 25) + '...' : text;
        }

        // Ajouter le message utilisateur
        const userMsg = { sender: 'user', text: text };
        currentChat.messages.push(userMsg);
        appendMessageToDOM(userMsg);
        saveToLocalStorage();
        renderHistory();

        // Simulation de la réponse IA après un court délai
        setTimeout(() => {
            simulateAIResponse(currentChat);
        }, 600);
    }

    function simulateAIResponse(chat) {
        // Choix aléatoire d'une réponse
        const randomResponse = aiResponses[Math.floor(Math.random() * aiResponses.length)];
        const aiMsg = { sender: 'ai', text: '' };

        chat.messages.push(aiMsg);
        saveToLocalStorage();

        // Création du conteneur du message IA dans le DOM
        const messageDiv = document.createElement('div');
        messageDiv.className = 'message ai';
        messageDiv.innerHTML = `
            <div class="message-content">
                <div class="message-avatar"><i class="fa-solid fa-robot"></i></div>
                <div class="message-text"></div>
            </div>
        `;
        messagesContainer.appendChild(messageDiv);
        scrollToBottom();

        const textElement = messageDiv.querySelector('.message-text');
        let charIndex = 0;

        // Effet de frappe (Typing Effect)
        function typeWriter() {
            if (charIndex < randomResponse.length) {
                aiMsg.text += randomResponse.charAt(charIndex);
                textElement.textContent = aiMsg.text;
                charIndex++;
                scrollToBottom();
                setTimeout(typeWriter, 15); // Vitesse de frappe
            } else {
                saveToLocalStorage();
            }
        }

        typeWriter();
    }

    function appendMessageToDOM(msg) {
        const messageDiv = document.createElement('div');
        messageDiv.className = `message ${msg.sender}`;

        const iconClass = msg.sender === 'user' ? 'fa-user' : 'fa-robot';

        messageDiv.innerHTML = `
            <div class="message-content">
                <div class="message-avatar"><i class="fa-solid ${iconClass}"></i></div>
                <div class="message-text"></div>
            </div>
        `;

        messageDiv.querySelector('.message-text').textContent = msg.text;
        messagesContainer.appendChild(messageDiv);
        scrollToBottom();
    }

    function renderMessages(messages) {
        messagesContainer.innerHTML = '';

        if (messages.length === 0) {
            messagesContainer.innerHTML = `
                <div class="welcome-screen" id="welcomeScreen">
                    <div class="welcome-icon"><i class="fa-solid fa-robot"></i></div>
                    <h2>Comment puis-je vous aider aujourd'hui ?</h2>
                    <p>Posez-moi une question, demandez du code ou discutez simplement.</p>
                </div>
            `;
            return;
        }

        messages.forEach(msg => {
            appendMessageToDOM(msg);
        });
    }

    function renderHistory() {
        historyContainer.innerHTML = '';
        chats.forEach(chat => {
            const item = document.createElement('div');
            item.className = `history-item ${chat.id === currentChatId ? 'active' : ''}`;
            item.textContent = chat.title;
            item.addEventListener('click', () => {
                currentChatId = chat.id;
                localStorage.setItem('current_chat_id', currentChatId);
                renderMessages(chat.messages);
                renderHistory();
                if (window.innerWidth <= 768) sidebar.classList.remove('open');
            });
            historyContainer.appendChild(item);
        });
    }

    function saveToLocalStorage() {
        localStorage.setItem('chat_history', JSON.stringify(chats));
        localStorage.setItem('current_chat_id', currentChatId);
    }

    function loadChat(chatId) {
        currentChatId = chatId;
        const chat = chats.find(c => c.id === chatId);
        if (chat) {
            renderMessages(chat.messages);
        }
        renderHistory();
    }

    function scrollToBottom() {
        messagesContainer.scrollTop = messagesContainer.scrollHeight;
    }
});
```

